function getSprite(assetPath) {
  const key = String(assetPath || '').split('/').pop().replace(/\.svg$/, '')
  const row = SPRITES[key]
  if (!row) return null
  const size = SHEET_SIZES[row[0]]
  return {
    image: SHEET_IMAGES[row[0]],
    x: row[1],
    y: row[2],
    width: row[3],
    height: row[4],
    sheetWidth: size[0],
    sheetHeight: size[1]
  }
}

module.exports = { SHEET_IMAGES, SHEET_SIZES, SPRITES, getSprite };
